INSERT INTO "game_descs" ("id", "row_no", "name", "res", "text") VALUES
  (9317, 4751, '无双铠（男）', '', '战士3级服装'),
  (9318, 4752, '无双铠（女）', '', '战士3级服装'),
  (9319, 4753, '黑麒铠（男）', '', '战士4级服装'),
  (9320, 4754, '黑麒铠（女）', '', '战士4级服装'),
  (9321, 4755, '白金护额', '', '无比坚固的白金制作的护额，但是由于白金过于昂贵，所以一般白金所护的地方只是额头的正前方'),
  (9322, 4756, '潜杀之首', '', '用特殊材料制作的不反光的黑色头罩，能把头全部包住，为暗杀者之首选'),
  (9323, 4757, '魔语帽', '', '形状诡异的帽子，戴上它之后会经常听到莫名的呢喃，但是因为具有不错的防御力，所以很多人宁愿忍受这喃喃魔语也要戴着'),
  (9324, 4758, '升灵冠', '', '传说修道得仙的道士在升仙之前所戴的帽子，拥有非常纯粹的仙灵之气，非常难得'),
  (9325, 4759, '红缨之风', '', '坚硬又薄的外壳，让佩戴者看起来英姿飒爽，头顶上的红缨看起来像在空中飘动'),
  (2219, 476, '圣*朱小兜男衣', '', ''),
  (9326, 4760, '缚神巾', '', '用来缚住长发使之不遮挡双眼的头巾，但是缚神巾里面嵌入了少量星尘沙，能使佩带者凝神炼心，精神无比集中，故得名'),
  (9327, 4761, '药师冠', '', '正式获得药师资格者所戴的帽子，比月白帽和药童帽都要大一些，也华丽一些'),
  (9328, 4762, '天兰冠', '', '天兰一般长在仙界，人间难得一见，获得天兰的人都会认为这是神的赐予，药师把它戴在头上，也是为了获得神的赐福'),
  (9329, 4763, '魔牛角', '', '牛角样子的恶魔角,邪恶的威严感,使人望而生畏.'),
  (9330, 4764, '血战头巾', '', '写有必胜两个字的白色头带，十分抢眼，代表着热血的决心，能在战斗的时候提升士气'),
  (9331, 4765, '白金护腕', '', '使用坚固的白金制作成的防具,拥有很强的防御力,但重量也很沉重,会使行动力会很缺乏.'),
  (9332, 4766, '荣誉护腕', '', '精炼的钢铁，精致的纹理，构成了高贵，美丽的装备。其是为获得特殊荣耀的勇士们所准备的。'),
  (9333, 4767, '晨星之光', '', ''),
