INSERT INTO "game_descs" ("id", "row_no", "name", "res", "text") VALUES
  (10679, 5471, '七彩糖果*赤', '', '使用后5分钟内，人物物理暴击率提高10%。'),
  (10680, 5472, '七彩糖果*橙', '', '使用后5分钟内，人物魔法暴击率提高10%。'),
  (10681, 5473, '七彩糖果*黄', '', '使用后立即回复人物血量30%，无冷却时间。'),
  (10682, 5474, '七彩糖果*绿', '', '使用后立即回复人物法力30%，无冷却时间。'),
  (10683, 5475, '七彩糖果*青', '', '使用后5分钟内，物理攻击力提高30%。'),
  (10684, 5476, '七彩糖果*蓝', '', '使用后5分钟内，魔法攻击力提高30%。'),
  (10685, 5477, '七彩糖果*紫', '', '使用后5分钟内，不良抗性增加10%。'),
  (10687, 5478, '潜龙出海', '', '潜龙出海，蕴含着神龙的灵魄，双击后对项链使用，即可融合在项链上，提高人物基础能力数值力量、敏捷、体质、智慧、精神五项属性的2%。凑满10个即可找NPC龙啸九天兑换加成能力更高的见龙在田。'),
  (10688, 5479, '见龙在田', '', '见龙在田，蕴含着神龙的灵魄，双击后对项链使用，即可融合在项链上，提高人物基础能力数值力量、敏捷、体质、智慧、精神五项属性的4%。凑满3个即可找NPC龙啸九天兑换加成能力更高的神龙摆尾。'),
  (2291, 548, '真*随蜂起舞男', '', ''),
  (10689, 5480, '神龙摆尾', '', '神龙摆尾，蕴含着神龙的灵魄，双击后对项链使用，即可融合在项链上，提高人物基础能力数值力量、敏捷、体质、智慧、精神五项属性的6%。凑满5个即可找NPC中国必胜兑换加成能力更高的龙啸九天和龙啸九天称号石。'),
  (10690, 5481, '龙啸九天', '', '龙啸九天，蕴含着神龙的灵魄，双击后对项链使用，提高人物基础能力数值力量、敏捷、体质、智慧、精神五项属性的9%。'),
  (10691, 5482, '中国必胜', '', '蕴含着神龙的灵魄和龙之力量，双击后对武器使用，即可融合在武器上，提高人物基础能力数值力量、敏捷、体质、智慧、精神五项属性的24%。此外装备融合有该元素的武器，游戏角色能获得全新超级酷炫特殊光效称号“中国必胜”。'),
  (10692, 5483, '2010！中国腾飞称号石', '', '玩家用“2010！中国腾飞”兑换“2012！中国必胜”时获得的纪念石，双击后任务称号里游戏服务期间可用增加酷炫特殊光效称号“2010！中国腾飞”。'),
  (10693, 5484, '中国必胜称号石', '', '双击后任务称号里游戏服务期间可用增加酷炫特殊光效称号“中国必胜”。'),
  (10694, 5485, '龙啸九天称号石', '', '玩家用“神龙摆尾”兑换“龙啸九天”时获得的纪念石，双击后任务称号里游戏服务期间可用增加酷炫特殊称号“龙啸九天”。'),
  (10757, 5486, '封印的涅磐之书', '', '能给宠物带来觉醒之力的神奇之书,用凤凰之血可以为其解除封印,提升等级后才可以使用'),
  (10758, 5487, '凤凰之血', '', '传说中凤凰涅磐之血，据说拥有能让人脱胎换骨的神奇力量。'),
  (10759, 5488, '+1涅磐之书', '', '能给宠物带来觉醒之力的神奇之书,用凤凰之血可以为其提升等级'),
  (10760, 5489, '+2涅磐之书', '', '能给宠物带来觉醒之力的神奇之书,用凤凰之血可以为其提升等级,只有觉醒等级+1的宠物才可以使用'),
  (2292, 549, '真*随蜂起舞女', '', ''),
  (10761, 5490, '+3涅磐之书', '', '能给宠物带来觉醒之力的神奇之书,用凤凰之血可以为其提升等级,只有觉醒等级+2的宠物才可以使用'),
  (10762, 5491, '+4涅磐之书', '', '能给宠物带来觉醒之力的神奇之书,用凤凰之血可以为其提升等级,只有觉醒等级+3的宠物才可以使用'),
  (10763, 5492, '+5涅磐之书', '', '能给宠物带来觉醒之力的神奇之书,用凤凰之血可以为其提升等级,只有觉醒等级+4的宠物才可以使用'),
  (10764, 5493, '+6涅磐之书', '', '能给宠物带来觉醒之力的神奇之书,用凤凰之血可以为其提升等级,只有觉醒等级+5的宠物才可以使用'),
  (10765, 5494, '+7涅磐之书', '', '能给宠物带来觉醒之力的神奇之书,用凤凰之血可以为其提升等级,只有觉醒等级+6的宠物才可以使用'),
  (10766, 5495, '+8涅磐之书', '', '能给宠物带来觉醒之力的神奇之书,用凤凰之血可以为其提升等级,只有觉醒等级+7的宠物才可以使用'),
  (10767, 5496, '+9涅磐之书', '', '能给宠物带来觉醒之力的神奇之书,用凤凰之血可以为其提升等级,只有觉醒等级+8的宠物才可以使用'),
  (10768, 5497, '+10涅磐之书', '', '能给宠物带来觉醒之力的神奇之书,用凤凰之血可以为其提升等级,只有觉醒等级+9的宠物才可以使用'),
  (10769, 5498, '金甲之魂', '', '对觉醒等级＋１０的的部分坐骑使用，可以使坐骑外形发生华丽的变化（可以使用的坐骑有：九眼妖虎、仙圣麒麟、火鸟、地翼魔、螃蟹、蜘蛛、年兽*瑞麒、年兽*祥麟、仙麒麟、 圣麒麟、碧海云天狮、顺风飞天马、独角兽、苍狼皇）'),
  (10770, 5499, '银甲之魂', '', '对觉醒等级＋７以上的部分坐骑使用，可以使坐骑外形发生华丽的变化（可以使用的坐骑有：九眼妖虎、仙圣麒麟、火鸟、地翼魔、螃蟹、蜘蛛、年兽*瑞麒、年兽*祥麟、仙麒麟、 圣麒麟、碧海云天狮、顺风飞天马、独角兽、苍狼皇）'),
